class Solution:
    def maxSumMinProduct(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        stack = []
        best = 0
        for i in range(n + 1):
            cur = nums[i] if i < n else 0
            while stack and nums[stack[-1]] >= cur:
                h = nums[stack.pop()]
                l = stack[-1] + 1 if stack else 0
                best = max(best, h * (pre[i] - pre[l]))
            stack.append(i)
        return best % (10 ** 9 + 7)

