class Solution {
    public int maxSumMinProduct(int[] nums) {
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        Deque<Integer> st = new ArrayDeque<>();
        long best = 0;
        for (int i = 0; i <= n; i++) {
            long cur = i < n ? nums[i] : 0;
            while (!st.isEmpty() && nums[st.peek()] >= cur) {
                long h = nums[st.pop()];
                long l = st.isEmpty() ? 0 : st.peek() + 1;
                best = Math.max(best, h * (pre[i] - pre[l]));
            }
            st.push(i);
        }
        return (int) (best % 1_000_000_007L);
    }
}

