var maxSumMinProduct = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const pre = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + BigInt(nums[i]);
    const stack = [];
    let best = 0n;
    for (let i = 0; i <= n; i++) {
        const cur = i < n ? BigInt(nums[i]) : 0n;
        while (stack.length && BigInt(nums[stack[stack.length - 1]]) >= cur) {
            const h = BigInt(nums[stack.pop()]);
            const l = stack.length ? stack[stack.length - 1] + 1 : 0;
            const cand = h * (pre[i] - pre[l]);
            if (cand > best) best = cand;
        }
        stack.push(i);
    }
    return Number(best % MOD);
};
